svg.script:
(()=>{'use strict';
const svg=document.getElementById('nightOff'),$=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
const DURATION=120,GROUND=560,DOGX=300;let last=0,idle=0,mobile=false,compact=false,seed=71,sound=false,audio=null,best=0,unlocked=[];
const reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
const defaults={phase:'cover',mode:'film',t:0,paused:false,y:0,vy:0,jumps:0,dash:0,cool:0,inv:0,coffee:0,hits:0,smashed:0,distance:0,spawn:.6,chapter:0,ending:'',toast:0,shake:0,combo:0,maxCombo:0,comboTime:0,energy:0,freedom:0,superUses:0,nearMiss:0,jumpBuffer:0,score:0,beat:-1,spawnIndex:0,completedMain:false,bossEligible:false,bossWon:false};
const S={...defaults};let items=[],particles=[],ripples=[];
try{best=Number(localStorage.getItem('nightOffBestV2'))||0;let u=JSON.parse(localStorage.getItem('nightOffBadgesV2')||'[]');if(Array.isArray(u))unlocked=u.filter(x=>['天亮了','三杯续命','消息免疫','脱缰野狗','不批不改'].includes(x))}catch(e){}
const subtitles=[[0,'凌晨 02:17。群里还在问：在吗？'],[7,'在。但不在工位。'],[14,'第一幕 / 把加班留在雨里。'],[21,'左手跳，右手冲。今晚你自己掌方向。'],[27,'第二幕 / 深夜小店，全都还亮着。'],[36,'捡够六杯冰美式，给世界静个音。'],[46,'把那些“改一下”，甩在上一条街。'],[55,'跑慢一点也行。别把自己交出去。'],[58,'第三幕 / 高架底下，风把声音拉长。'],[67,'前方的通知会排队。不用回。跳过去。'],[78,'零受击的人，能走一条没人审批的路。'],[87,'第四幕 / 邕江的风，不查你的考勤。'],[94,'你看。被拒收的通知，折成了一条鲸。'],[102,'别追它。它知道哪边是海。'],[109,'有钱有有钱的活法。没钱也能兜风。'],[116,'今天可以收工。除非你还想拆点东西。']];
const attr=(e,k,v)=>{v=String(v);if(e.getAttribute(k)!==v)e.setAttribute(k,v)};
const set=(id,k,v)=>attr($(id),k,v),text=(id,t)=>{const e=$(id);if(e.textContent!==t)e.textContent=t};
const show=(id,yes)=>$(id).classList.toggle('hide',!yes);
function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function node(tag,attrs={}){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))attr(n,k,v);return n}
function unlockAudio(){if(!sound||S.paused)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume().catch(()=>{})}catch(e){sound=false;text('soundText','音效：关')}}
function beep(f=400,len=.1,type='sine',vol=.04){if(!sound||!audio||audio.state!=='running')return;try{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime;o.type=type;o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(Math.max(40,f*.65),t+len);g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+len);o.connect(g);g.connect(audio.destination);o.start();o.stop(t+len);o.onended=()=>{o.disconnect();g.disconnect()}}catch(e){}}
function music(){const beat=Math.floor(S.t/.43);if(beat===S.beat)return;S.beat=beat;if(!sound)return;const notes=[220,0,329.63,261.63,0,293.66,329.63,0,196,246.94,0,293.66,0,329.63,261.63,0];const n=notes[beat%notes.length];if(n)beep(n*(S.chapter>=3?1.5:1),.25,'sine',.013);if(beat%4===0)beep(82,.18,'triangle',.018)}
function clearWorld(){for(const o of items)o.el.remove();for(const p of particles)p.el.remove();for(const r of ripples)r.el.remove();items=[];particles=[];ripples=[]}
function start(mode){resetBoss();clearWorld();seed=71;Object.assign(S,defaults,{phase:'running',mode});svg.classList.remove('paused');text('pauseText','暂停');show('cover',false);show('ending',false);show('hud',true);show('skillHud',true);show('subtitle',true);last=performance.now();if(sound)unlockAudio();render();beep(620,.12)}
function home(){resetBoss();clearWorld();Object.assign(S,defaults);svg.classList.remove('paused');for(const id of['ending','hud','skillHud','subtitle','revealCaption','freedomBanner'])show(id,false);show('cover',true);text('pauseText','暂停');render()}
function pause(force){if(!['running','boss','bossVictory'].includes(S.phase))return;S.paused=typeof force==='boolean'?force:!S.paused;svg.classList.toggle('paused',S.paused);text('pauseText',S.paused?'继续':'暂停');if(sound&&audio){try{(S.paused?audio.suspend():audio.resume()).catch(()=>{})}catch(e){}}else if(sound&&!S.paused)unlockAudio();last=performance.now()}
function jump(){if(!['running','boss'].includes(S.phase)||S.paused||S.mode==='film')return;if(S.jumps>=2){S.jumpBuffer=.13;return}jumpCore()}
function jumpCore(){S.vy=S.jumps===0?-635:-570;S.jumps++;S.jumpBuffer=0;puff(DOGX-17,GROUND+S.y,7,'#c8e1d1');if(sound)unlockAudio();beep(S.jumps===1?430:630,.09)}
function dash(){if(!['running','boss'].includes(S.phase)||S.paused||S.mode==='film'||S.cool>0)return;dashCore()}
function dashCore(){S.dash=.57;S.cool=S.phase==='boss'?1.1:S.freedom>0?1.6:3.2;S.inv=Math.max(S.inv,.68);puff(DOGX-60,GROUND+S.y-55,10,'#8bf4d4');if(sound)unlockAudio();beep(180,.2,'sawtooth',.025);if(S.phase==='boss')shootBoss(S.freedom>0?2:1)}
function superMove(){if(!['running','boss'].includes(S.phase)||S.paused||S.mode==='film')return;activateFreedom()}
function activateFreedom(){if(S.energy<6||S.freedom>0)return;S.energy=0;S.freedom=3.8;S.superUses++;S.inv=Math.max(S.inv,4.15);S.cool=0;S.shake=reduced?0:.15;toast('全群消息，已静音。');puff(DOGX+15,GROUND+S.y-55,25,'#fff0b4');beep(780,.3,'triangle',.045);if(S.phase==='boss'&&B.state==='open')shootBoss(2)}
function gainEnergy(n=1){if(S.freedom===0)S.energy=Math.min(6,S.energy+n)}
function combo(){S.combo++;S.comboTime=4.5;S.maxCombo=Math.max(S.maxCombo,S.combo)}
function puff(x,y,count,color){count=Math.min(count,reduced?3:28);for(let i=0;i<count&&particles.length<92;i++){const el=node('circle',{cx:x,cy:y,r:2+Math.random()*4,fill:color});$('particles').appendChild(el);particles.push({el,x,y,vx:(Math.random()-.75)*190,vy:(Math.random()-.85)*160,life:.45+Math.random()*.35,max:.8})}}
function ripple(x=300){if(ripples.length>5){ripples.shift().el.remove()}const el=node('ellipse',{cx:x,cy:566,rx:18,ry:3,fill:'none',stroke:'#a5ddcf','stroke-width':1.5});$('landingRipples').appendChild(el);ripples.push({el,life:.65})}
function toast(message,color='#b3f2db'){S.toast=.85;text('feedbackText',message);set('feedbackText','fill',color)}
function spawn(){const patterns=[['coffee',-54],['folder',0],['coffee',-145],['coffee',-220],['notice',0],['coffee',-54],['coffee',-145],['folder',0],['coffee',-54],['notice',0],['coffee',-145],['coffee',-54]];const [type,height]=patterns[S.spawnIndex%patterns.length];S.spawnIndex++;const coffee=type==='coffee',x=mobile?930:1400,el=node('use',{href:'#'+type,x:-40,y:coffee?-67:-90,width:80,height:coffee?80:96}),g=node('g');g.appendChild(el);$('items').appendChild(g);items.push({el:g,x,y:GROUND+height,coffee,type,done:false,phase:rnd()*7,minDy:1000,near:false})}

function score(){return Math.max(0,S.coffee*10+S.smashed*20+S.nearMiss*12+S.maxCombo*5-S.hits*3+(S.bossWon?400:0))}
function end(){S.phase='ending';S.paused=false;svg.classList.remove('paused');for(const id of['hud','skillHud','subtitle','revealCaption','freedomBanner','perfectBadge','bossHud','bossCallout','bossGate','bossResult','bossWorld'])show(id,false);show('ending',true);let title,line;
if(S.bossWon){title='终审作废，准时自由';line='审批机终于安静了。江风不需要盖章。'}
else if(S.mode==='film'){title='今天不改了';line='通知折成鲸。凌晨，还给自己。'}
else if(S.superUses>=2&&S.maxCombo>=8&&S.hits<=5){title='野狗，彻底脱缰';line='不批假，不申请。整个夜晚都是你的。'}
else if(S.coffee>=15){title='咖啡因自由人';line='账上未必有米，血里全是冰美式。'}
else if(S.hits>=9){title='带薪精神离职';line='人被催到了。灵魂已在邕江边兜风。'}
else{title='无米，但自由';line='明天再想钱。今天先把风吹够。'}
S.ending=title;S.score=score();text('endTitle',title);text('endLine',line);text('endStats',`咖啡 ${S.coffee} / 撞飞 ${S.smashed} / 擦身 ${S.nearMiss} / 连击 ${S.maxCombo}`);
let earned=[];if(S.mode==='play'){earned.push('天亮了');if(S.bossWon)earned.push('不批不改');if(S.coffee>=12)earned.push('三杯续命');if(S.smashed>=5)earned.push('消息免疫');if(S.ending==='野狗，彻底脱缰')earned.push('脱缰野狗');let fresh=earned.filter(x=>!unlocked.includes(x));unlocked=[...new Set([...unlocked,...earned])];best=Math.max(best,S.score);try{localStorage.setItem('nightOffBestV2',String(best));localStorage.setItem('nightOffBadgesV2',JSON.stringify(unlocked))}catch(e){}text('badgeText',fresh.length?`新徽章 / ${fresh.join(' · ')}`:`本地徽章 ${unlocked.length} / 5 · 再逃一次？`)}else text('badgeText','亲自逃班，可收集 5 枚本地徽章');
text('bestText',S.mode==='film'?'放映完毕 / 现在轮到你':'自由分 '+S.score+' · 最佳 '+best+' · 被催 '+S.hits+' 次');text('ticketHint','票根是一张 SVG，不上传数据。');beep(760,.28)}
function updateFX(dt){particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;attr(p.el,'cx',p.x);attr(p.el,'cy',p.y);attr(p.el,'opacity',Math.max(0,p.life/p.max));if(p.life<=0)p.el.remove();return p.life>0});ripples=ripples.filter(r=>{r.life-=dt;const t=.65-r.life;attr(r.el,'rx',18+t*85);attr(r.el,'ry',3+t*10);attr(r.el,'opacity',Math.max(0,r.life/.65)*.5);if(r.life<=0)r.el.remove();return r.life>0})}
function step(dt){if(S.paused)return;if(['boss','bossVictory'].includes(S.phase)){stepBoss(dt);return}if(S.phase!=='running')return;S.t=Math.min(DURATION,S.t+dt);S.chapter=S.t<27?0:S.t<58?1:S.t<87?2:3;const revealSlow=S.t>92&&S.t<101?.72:1,speed=(235+S.chapter*27)*revealSlow*(S.dash>0?1.75:S.freedom>0?1.16:1);S.distance+=speed*dt;for(const k of['cool','dash','inv','toast','shake','comboTime','jumpBuffer','freedom'])S[k]=Math.max(0,S[k]-dt);if(S.comboTime===0)S.combo=0;music();
if(S.mode==='film'){const near=items.find(o=>!o.done&&o.x>DOGX+35&&o.x<DOGX+175);if(near&&!near.coffee&&S.cool===0)dashCore();if(near&&near.coffee&&near.y<GROUND-100&&S.y===0)jumpCore();if(S.energy===6&&S.freedom===0)activateFreedom()}
const wasAir=S.y<0;S.vy+=1600*dt;S.y+=S.vy*dt;if(S.y>=0){S.y=0;S.vy=0;S.jumps=0;if(wasAir){ripple();puff(DOGX,GROUND,5,'#8fcac4');if(S.jumpBuffer>0)jumpCore()}}S.spawn-=dt;if(S.spawn<=0&&S.t<113){if(S.t<90||S.t>101)spawn();S.spawn=[1.48,1.34,1.17,1.42][S.chapter]+rnd()*.18}
for(const o of items){o.x-=speed*dt;const dogCenter=GROUND+S.y-65;const magnetic=S.freedom>0&&o.coffee&&Math.abs(o.x-(DOGX+17))<360;if(magnetic){o.x+=(DOGX+17-o.x)*Math.min(1,dt*4.6);o.y+=(dogCenter+29-o.y)*Math.min(1,dt*5.5)}const dy=o.coffee?Math.sin(S.t*3+o.phase)*4:0;attr(o.el,'transform',`translate(${o.x},${o.y+dy})`);const dx=Math.abs(o.x-(DOGX+17)),objCenter=o.y+(o.coffee?-29:-37),vertical=Math.abs(dogCenter-objCenter);const coll=dx<(o.coffee?62:64)&&vertical<(o.coffee?57:64);
if(!o.coffee&&dx<65)o.minDy=Math.min(o.minDy,vertical);
if(!o.done&&coll){if(o.coffee){S.coffee++;gainEnergy();combo();o.done=true;toast(S.energy===6?'咖啡满了 / 按 E 自由模式':'冰美式 +1','#ffe0a1');puff(o.x,o.y-35,10,'#ffd89c');beep(980+Math.min(S.combo,12)*20,.1)}else if(S.dash>0||S.freedom>0){S.smashed++;gainEnergy(.5);combo();o.done=true;toast(S.combo>=3?'不改了 ×'+S.combo:'KPI 已下线');S.shake=reduced?0:.12;puff(o.x,o.y-30,16,'#ff9ac1');beep(120,.12,'triangle')}else if(S.mode==='film'||S.inv>0){o.done=true}else{S.hits++;S.inv=1.35;S.combo=0;S.comboTime=0;o.done=true;toast('收到，但不改。','#ffb2ce');S.shake=reduced?0:.17;puff(DOGX+20,GROUND+S.y-70,10,'#ff9dba');beep(95,.18,'square',.02)}}
if(!o.done&&!o.coffee&&!o.near&&o.x<DOGX-52){o.near=true;if(o.minDy>=64&&o.minDy<145&&S.inv<=0){S.nearMiss++;gainEnergy(.5);combo();toast('擦身而过 +12','#a7d9ff');puff(DOGX-28,GROUND+S.y-25,8,'#b1d8ff');beep(540,.12)}}if(o.x<-120)o.done=true}
items=items.filter(o=>{if(o.done)o.el.remove();return!o.done});updateFX(dt);if(S.t>=DURATION)finishMain()}
function render(){const running=['running','boss','bossVictory'].includes(S.phase),clock=['boss','bossVictory','bossResult'].includes(S.phase)?DURATION+B.t:S.phase==='cover'?idle:S.t,dist=S.phase==='cover'?idle*36:S.distance,dawn=S.phase==='cover'?0:Math.max(0,Math.min(1,(S.t-84)/32));
set('world','transform',S.shake>0?`translate(${Math.sin(clock*140)*S.shake*15},${Math.cos(clock*110)*S.shake*9})`:'translate(0,0)');set('feedback','opacity',running?Math.min(1,S.toast*4):0);set('feedback','transform',`translate(0,${S.y-(.85-S.toast)*28})`);set('sunrise','opacity',dawn);set('sunrise','transform',`translate(0,${(1-dawn)*100})`);set('dawn','opacity',dawn);set('stars','opacity',1-dawn*.95);set('moon','opacity',1-dawn*.75);set('moon','transform',`translate(${mobile?675:1050},${mobile?-20:95})`);set('farCity','transform',`translate(${-dist*.12%1600},0)`);set('clouds','transform',`translate(${-dist*.026%200},0)`);set('shops','transform',`translate(${-dist*.48%1600},0)`);set('shops','opacity',Math.max(0,1-dawn*1.4));set('river','opacity',Math.min(1,dawn*1.7));set('props','transform',`translate(${-dist*.77%1150},0)`);set('props','opacity',1-dawn*.6);set('roadMarks','transform',`translate(${-dist%190},0)`);set('reflections','transform',`translate(${-dist*.3%180},0)`);set('rain','opacity',reduced?0:.25*(1-dawn*.85));set('rain','transform',`translate(${-clock*44%120},${clock*380%260-190})`);set('drone','transform',`translate(${DOGX+245+Math.sin(clock*.8)*37},${205+Math.sin(clock*1.4)*18})`);set('drone','opacity',Math.max(0,1-dawn*1.4));
const whale=S.t>92&&S.phase==='running'?Math.min(1,(S.t-92)/2)*Math.max(0,Math.min(1,(117-S.t)/4)):0,whaleX=(mobile?570:850)-(S.t-95)*10;set('whaleReveal','opacity',whale*.9);set('whaleReveal','transform',`translate(${whaleX},${(mobile?210:235)+Math.sin(clock*.7)*15}) scale(${mobile?.82:1})`);set('paperWhale','transform',`rotate(${Math.sin(clock*.55)*3})`);show('revealCaption',S.phase==='running'&&S.t>94&&S.t<99);set('revealCaption','opacity',reduced?1:Math.min(1,(S.t-94)*2,(99-S.t)*2));
const catX=1100-(dist%1900);set('streetCat','transform',`translate(${catX},0)`);set('streetCat','opacity',S.phase!=='cover'&&S.chapter===1?.8:0);set('freedomAura','opacity',S.freedom>0?.65:0);set('freedomAura','transform',`translate(0,${S.y})`);set('auraRing','rx',118+Math.sin(clock*9)*8);set('speedRays','opacity',S.freedom>0&&!reduced?.22:0);set('speedRays','transform',`translate(${-clock*420%70},0)`);
const beat=clock*(running?17:7),stride=S.y<0?0:Math.sin(beat)*24;set('dog','transform',`translate(${DOGX},${GROUND+S.y})`);set('dogBody','transform',`translate(0,${S.y<0?0:Math.abs(Math.sin(beat))*-3}) rotate(${S.dash>0?-7:S.y<0?-5:0})`);set('legBack','transform',`rotate(${stride},-25,-43)`);set('legFront','transform',`rotate(${-stride},28,-44)`);set('tail','transform',`rotate(${Math.sin(clock*12)*7},-45,-70)`);set('dog','opacity',S.inv>0&&S.dash===0&&S.freedom===0?(Math.sin(clock*35)>0?.5:1):1);set('dogShadow','opacity',Math.max(.13,1+S.y/350));set('dashTrail','opacity',S.dash>0?.85:S.freedom>0?.4:0);set('dashTrail','transform',`translate(0,${S.y})`);set('dogReflection','transform',`translate(${DOGX},${572-S.y*.35}) scale(1,-.34)`);
text('coffeeText',`冰美式 ${S.coffee}`);text('hitText',`被催 ${S.hits} 次`);text('chapterText',['01 / 雨夜离席','02 / 街头续命','03 / 高架夜跑','04 / 江风自由'][S.chapter]);text('comboText','连击 '+S.combo);text('energyText',S.freedom>0?'自由':Math.floor(S.energy)+' / 6');set('energyFill','d','M137 25h'+(119*(S.freedom>0?S.freedom/3.8:S.energy/6)));text('dashLabel',S.cool>0?`冷却 ${S.cool.toFixed(1)}s`:'冲刺 →');const playing=running&&S.mode==='play';set('jumpBtn','opacity',playing?1:.38);set('dashBtn','opacity',playing?(S.cool>0?.6:1):.38);set('superBtn','opacity',playing?1:.45);$('superBtn').classList.toggle('ready',playing&&S.energy===6);text('superLabel',S.freedom>0?'自由 '+S.freedom.toFixed(1)+'s':'自由模式');text('superHint',S.energy===6?'点击 / E 释放':'冰美式 '+Math.floor(S.energy)+' / 6');set('superMeter','width',superWidth*(S.freedom>0?S.freedom/3.8:S.energy/6));set('dashMeter','width',dashWidth*(1-Math.min(1,S.cool/(S.phase==='boss'?1.1:S.freedom>0?1.6:3.2))));show('freedomBanner',S.phase==='running'&&S.freedom>0);set('progressFill','width',(mobile?640:1200)*S.t/DURATION);text('timerText',S.phase==='cover'?'SVG / 导演剪辑版':S.phase==='boss'?`Boss / ${Math.floor(B.t)} 秒`:`${S.mode==='film'?'放映':'逃班'} / ${Math.floor(S.t).toString().padStart(3,'0')} : 120`);
if(S.phase==='running'){let line=subtitles[0][1];for(const[t,s]of subtitles)if(S.t>=t)line=s;text('subtitleLine',line);const d=Math.min(Math.abs(S.t-27),Math.abs(S.t-58),Math.abs(S.t-87));set('transition','opacity',!reduced&&d<.32?(1-d/.32)*.48:0)}else set('transition','opacity',0);
set('overpass','opacity',S.phase==='running'&&S.chapter===2?.82:0);set('overpass','transform',`translate(${-dist*.32%377},0)`);show('perfectBadge',S.phase==='running'&&S.mode==='play');text('perfectText',S.hits===0?'零受击 / 隐藏路线保持中':'隐藏路线未达成 / 仍可收工');set('perfectText','fill',S.hits===0?'#b3f3da':'#c3a6b9');renderBoss();
text('hintText',S.phase==='boss'?'先躲预警 / 绿盾开窗时冲刺反击':running&&S.mode==='play'&&S.t<6?'左手跳 / 右手冲 / 按下即动，试试一起按':S.phase==='cover'?'放映看故事 / 逃班亲自玩 / 左跳 · 右冲 · 中间大招':S.mode==='film'?'自动放映中 / 开音效可听轻量合成配乐':mobile?'左跳 · 右冲 · 六杯咖啡开自由模式':'空格 二段跳 · Shift 冲刺 · E 自由模式 · P 暂停')}
let superWidth=240,dashWidth=218;
function frame(now){let delta=Math.max(0,(now-last)/1000||0);last=now;if(!S.paused){idle+=Math.min(delta,.08);if(['running','boss','bossVictory'].includes(S.phase)){delta=Math.min(delta,.1);while(delta>0){const dt=Math.min(delta,1/60);step(dt);delta-=dt}}}render();requestAnimationFrame(frame)}
function pos(id,x,y){set(id,'transform',`translate(${x},${y})`)}
function buttonSize(id,w,h){const b=$(id),rect=b.querySelector('rect'),label=b.querySelector('text');attr(rect,'width',w);attr(rect,'height',h);attr(label,'x',w/2);attr(label,'y',h/2+9);if(id==='dashBtn'){dashWidth=w-32;set('dashMeter','y',h-8)}}
