function escapeXML(s){return String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))}
function makeTicket(){const title=escapeXML(S.ending||'今天不改了'),when=new Date().toLocaleDateString('zh-CN');const body=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600" viewBox="0 0 1000 600"><defs><linearGradient id="a" x2="1" y2="1"><stop stop-color="#10243c"/><stop offset="1" stop-color="#223c49"/></linearGradient></defs><rect width="1000" height="600" rx="32" fill="url(#a)"/><path d="M35 100H965M35 480H965" stroke="#6aa996" stroke-dasharray="5 10"/><circle cx="0" cy="490" r="22" fill="#fff"/><circle cx="1000" cy="490" r="22" fill="#fff"/><g font-family="system-ui,sans-serif"><text x="62" y="67" fill="#9deccf" font-size="23" letter-spacing="6">NIGHT OFF / 野狗逃班</text><text x="62" y="175" fill="#ffe1a5" font-size="48" font-weight="800">${title}</text><text x="62" y="233" fill="#b7d7d2" font-size="24">从工位到江边 · 120秒${S.bossWon?" + Boss 已击破":""} · ${escapeXML(when)}</text><text x="62" y="300" fill="#e7f3db" font-size="26">冰美式 ${S.coffee}  / 撞飞KPI ${S.smashed}  / 擦身闪避 ${S.nearMiss}</text><text x="62" y="350" fill="#a7d3c5" font-size="24">最高连击 ${S.maxCombo}  / 自由模式 ${S.superUses}  / 自由分 ${score()}</text><text x="62" y="424" fill="#9ce4c7" font-size="24">把加班留在身后，把凌晨还给自己。</text><text x="62" y="547" fill="#8aaea8" font-size="20">ONE WAY / 不返工 · 此票根仅在你的设备生成</text></g><path d="M827 420q-38-120 26-133l36 7 24 74-76 19Z" fill="#f3c85e"/><path d="M870 289q20-36 40-16l7 24 29 8-10 24-35-6Z" fill="#cda575"/><circle cx="909" cy="291" r="4" fill="#102639"/><path d="M847 386l-9 37m52-38 18 35" stroke="#d5b183" stroke-width="13" stroke-linecap="round"/></svg>`;return body}
bind('ticketBtn',()=>{if(S.phase!=='ending')return;try{const blob=new Blob([makeTicket()],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElementNS('http://www.w3.org/1999/xhtml','a');a.href=url;a.download='野狗逃班-票根-'+Date.now()+'.svg';document.documentElement.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);text('ticketHint','票根已生成 / 请查看浏览器下载记录')}catch(e){text('ticketHint','这个预览器不支持保存，请用浏览器打开 HTML')}});
