const bossDefaults={t:0,hp:12,maxHP:12,player:3,stage:1,state:'intro',timer:3.5,elapsed:0,pattern:'low',cycle:0,pulse1:false,pulse2:false,hits:0,landed:0,blocked:0,won:false,flash:0,burst:0,notice:'',openSerial:0};
