function finishMain(){S.completedMain=true;S.bossEligible=S.mode==='play'&&S.hits===0;clearWorld();S.y=0;S.vy=0;S.jumps=0;S.dash=0;S.freedom=0;S.inv=0;S.cool=0;if(S.bossEligible){S.phase='bossGate';mainSnapshot={...S};for(const id of['hud','skillHud','subtitle','perfectBadge','revealCaption','freedomBanner'])show(id,false);show('bossGate',true);show('bossResult',false);show('ending',false);text('gateKicker','120 秒 / 零受击完美通关');beep(840,.3,'triangle')}else end()}
function startBoss(){if(!S.bossEligible&&!mainSnapshot)return;const keep=mainSnapshot||{...S};clearWorld();for(const o of shots)o.el.remove();shots=[];$('bossShots').replaceChildren();Object.assign(S,keep,{phase:'boss',paused:false,bossWon:false,y:0,vy:0,jumps:0,dash:0,cool:0,inv:0,freedom:0,energy:3,jumpBuffer:0,shake:0,toast:0,beat:-1});Object.assign(B,bossDefaults);svg.classList.remove('paused');for(const id of['bossGate','bossResult','ending','hud','perfectBadge','revealCaption','freedomBanner'])show(id,false);for(const id of['bossWorld','bossHud','bossCallout','skillHud','subtitle'])show(id,true);text('pauseText','暂停');text('subtitleLine','完美路线 / 终审官 · 永不下班');last=performance.now();if(sound)unlockAudio();render();beep(92,.4,'triangle',.04)}
function bossNext(){B.stage=B.hp>8?1:B.hp>4?2:3;const list=B.stage===1?['low','high']:B.stage===2?['double','low','high']:['double','high','double','low'];B.pattern=list[B.cycle%list.length];B.cycle++;B.state='telegraph';B.timer=B.stage===1?1.3:B.stage===2?1.2:1.1;B.elapsed=0;B.pulse1=false;B.pulse2=false;B.notice='';beep(B.pattern==='high'?330:160,.15,'triangle',.025)}
function bossDamage(){if(S.inv>0||S.dash>0||S.freedom>0||B.player<=0)return;B.player--;B.hits++;S.inv=1.3;S.combo=0;S.comboTime=0;S.shake=reduced?0:.2;toast('耐心 -1 / 先看预警','#ffbbbf');puff(DOGX+15,GROUND+S.y-55,16,'#ffadbc');beep(90,.2,'square',.022);if(B.player<=0)bossFail()}
function bossFail(){S.phase='bossResult';S.paused=false;S.freedom=0;S.dash=0;show('bossResult',true);for(const id of['bossHud','bossCallout','skillHud','subtitle','freedomBanner'])show(id,false);text('bossResultTitle','耐心用完了');text('bossResultLine','主关完美成绩还在。只重试这一战就行。');text('bossResultStats',`坚持 ${Math.floor(B.t)} 秒 / 命中 ${B.landed} 次 / Boss 剩 ${B.hp} 格`);render()}
function shootBoss(power){if(S.phase!=='boss'||B.state==='intro'||B.state==='phaseChange')return;const el=node('g');el.appendChild(node('path',{d:'M-15-7L20 0-15 7-6 0Z',fill:power>1?'#ffe0a1':'#9ef3da',stroke:'#effff0','stroke-width':1.5}));$('bossShots').appendChild(el);shots.push({el,x:DOGX+55,y:GROUND+S.y-78,power,life:1.8,dir:1,openAtLaunch:B.state==='open'});beep(620,.1,'triangle',.024)}
function hitBoss(power,openAtLaunch=false){if(B.state!=='open'&&!openAtLaunch){B.blocked++;B.notice='护盾还没开 / 先躲完这一轮';B.flash=.1;beep(240,.08,'sine',.02);return}B.hp=Math.max(0,B.hp-power);B.landed++;B.flash=.17;S.shake=reduced?0:.11;gainEnergy(1.5);combo();puff(mobile?610:890,359,14,'#ffe0b0');toast('反击命中 / -'+power,'#ffe0aa');beep(860,.18,'triangle',.038);if(B.hp===0){B.won=true;B.state='defeated';B.timer=3.2;B.burst=0;S.phase='bossVictory';S.bossWon=true;S.freedom=0;S.dash=0;S.inv=4;show('bossCallout',true);text('subtitleLine','终审作废。今晚，风说了算。');puff(mobile?610:890,337,28,'#b2ffe0')}else{const newStage=B.hp>8?1:B.hp>4?2:3;if(newStage>B.stage){B.stage=newStage;B.state='phaseChange';B.timer=2;B.notice='';S.cool=0;S.inv=Math.max(S.inv,.5);beep(140,.3,'sawtooth',.018)}}}
