if(S.phase==='bossVictory'){B.burst+=dt;B.timer-=dt;if(B.timer<=0)end();return}
const beat=Math.floor(B.t/.32);if(beat!==S.beat){S.beat=beat;if(sound&&beat%2===0)beep([110,146.83,164.81,130.81][Math.floor(beat/2)%4],.18,'triangle',.016)}
B.timer-=dt;if(B.state==='intro'&&B.timer<=0)bossNext();else if(B.state==='phaseChange'&&B.timer<=0)bossNext();else if(B.state==='telegraph'&&B.timer<=0){B.state='active';B.timer=B.pattern==='double'?1.45:1.1;B.elapsed=0;B.pulse1=false;B.pulse2=false;B.notice=''}else if(B.state==='active'){
if(B.pattern==='low'||B.pattern==='double'){if(B.elapsed>=.22&&B.elapsed<.38&&!B.pulse1&&S.y>-85){if(S.inv<=0&&S.dash<=0&&S.freedom<=0){B.pulse1=true;bossDamage()}}}else if(B.pattern==='high'){const cy=GROUND+S.y-65;if(B.elapsed>=.22&&B.elapsed<.48&&!B.pulse1&&cy>295&&cy<447){if(S.inv<=0&&S.dash<=0&&S.freedom<=0){B.pulse1=true;bossDamage()}}}
if(B.pattern==='double'){const cy=GROUND+S.y-65;if(B.elapsed>=.94&&B.elapsed<1.14&&!B.pulse2&&cy>295&&cy<447){if(S.inv<=0&&S.dash<=0&&S.freedom<=0){B.pulse2=true;bossDamage()}}}
if(S.phase==='boss'&&B.timer<=0){B.state='open';B.timer=B.stage===1?2.9:B.stage===2?2.7:2.55;B.elapsed=0;B.openSerial++;B.notice='';S.cool=Math.min(S.cool,.15);gainEnergy(1);beep(670,.18,'triangle',.03)}}else if(B.state==='open'&&B.timer<=0)bossNext();
