let message,color='#f3dcc1';if(B.state==='intro')message='左跳躲盖章 / 绿盾开窗后按冲刺';else if(B.state==='telegraph'){message=B.pattern==='low'?'地面盖章 / 准备跳跃':B.pattern==='high'?'空中催办 / 站在地面':'连环返工 / 先跳，后落地';color=B.pattern==='high'?'#e5b4ef':'#ffcea7'}else if(B.state==='active')message=B.pattern==='double'&&B.elapsed>.5?'第二拍：回到地面':'攻击执行中 / 躲过去';else if(B.state==='open'){message='护盾打开 / 冲刺反击！';color='#b3ffe0'}else if(B.state==='phaseChange'){message=B.stage===2?'二阶段 / 返工加速':'三阶段 / 最后一次审批';color='#ffb6cf'}else if(B.state==='defeated'){message='终审作废 / 今晚不返工';color='#b3ffe0'}else message='主关成绩保留';text('bossCalloutText',B.notice||message);set('bossCalloutText','fill',color);set('bossCalloutBg','stroke',color);if(S.phase==='boss')text('subtitleLine',B.state==='open'?'冲刺会发出反击纸飞机。命中后给自由模式充能。':B.state==='intro'?'零受击解锁的加场。三格耐心，失败只重试 Boss。':'看预警，不抢跳。高空催办时，站着就安全。');
